WITH matched_keys AS (SELECT id, customer_id FROM orders EXCEPT ALL SELECT id, customer_id FROM orders WHERE store_id IS NOT NULL), kept_rows AS (SELECT s.* FROM orders s INNER JOIN matched_keys k ON s.id = k.id AND s.customer_id = k.customer_id) SELECT customer_id, store_id, status, discount, shipping_fee, CASE WHEN status RLIKE '^(CANCELLED|SHIPPED)$' THEN 'PRIORITY' WHEN status RLIKE '^(COMPLETED|PENDING)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS status_zone FROM kept_rows ORDER BY customer_id NULLS LAST;
